.specs dl{margin:0;display:grid;grid-template-columns:repeat(4,auto);gap:4px 22px;}
.specs dt{font-size:10.5px;color:var(--muted);}
.specs dd{margin:0;font-family:var(--font-display);font-size:22px;font-weight:600;color:var(--gold);font-variant-numeric:tabular-nums;}
.specs small{display:block;margin-top:6px;font-size:10.5px;color:var(--muted);max-width:44ch;line-height:1.4;}
.stats{inset-inline-end:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));
  padding:10px 14px;font-family:var(--font-mono);font-size:11.5px;line-height:1.6;color:var(--muted);min-width:180px;}
.stats b{color:var(--text);font-weight:500;font-variant-numeric:tabular-nums;}
.stats .show b{color:var(--gold);}
#drSpeed{right:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;display:flex;align-items:baseline;gap:6px;color:var(--text);}   /* đồng hồ: dưới phải */
#drKmh{font:700 34px/1 var(--font-display);color:var(--gold);min-width:3ch;text-align:right;font-variant-numeric:tabular-nums;}
#drSpeedUnit{font-size:12px;}
#drHint{display:none;}
#drHint.off{opacity:0;transition:opacity .6s;}
@media (hover:hover){
  body.drive #drHint{display:block;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;}
}
/* Lái xe nhiều người: danh sách người chơi lên góc trên phải, dưới nút Thoát (đáy phải dành cho đồng hồ tốc độ, đáy trái cho bản đồ nhỏ, đáy phải trên cảm ứng cho bàn đạp); ar vẫn ở bên phải.
   Z-index 5 / 6 của danh sách và lời mời trên #drHud (4) nên bấm được trên lớp vuốt #drLook. Ô FPS (.stats, chỉ khi ?test) nhấc lên khỏi đồng hồ. Chế độ xem: không điều khiển, ẩn bàn đạp / cần gạt / gợi ý phím */
body.drive #exMpRoster:not([hidden]){inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));bottom:auto;top:calc(100px + env(safe-area-inset-top,0px));box-sizing:border-box;max-height:calc(100vh - 88px - var(--dr-gas-h,124px));overflow:hidden;}
body.compact.drive #exMpRoster:not([hidden]){top:calc(56px + env(safe-area-inset-top,0px));}
body.drive.ex-test .stats{bottom:calc(74px + env(safe-area-inset-bottom,0px));}
body.drive.ex-watching #drSteer,body.drive.ex-watching #drGas,body.drive.ex-watching #drBrake,body.drive.ex-watching #drLook,body.drive.ex-watching #drHint{display:none;}
@media (hover:none){
  body.drive.ex-watching #drSpeed{display:none;}   /* đồng hồ giữa trên đè dòng "Đang xem" */
}
body.drive #scene{cursor:grab;}
body.drive #scene:active{cursor:grabbing;}
/* Cảm ứng (hover:none): ngón trái cần gạt ngang dưới trái; ngón phải GA (to) và PHANH (nhỏ hơn, bên trái GA) dưới phải; vuốt vùng trống xoay camera.
   Kích thước từ CONFIG.drive.touch qua biến --dr-*; màn hẹp co theo bề rộng để ba nút không chồng nhau ở 390 px. Bản đồ nhỏ lên trái dưới hàng nút ⚙ / Thoát, đồng hồ giữa trên (đáy dành cho điều khiển) */

